const char* const UI_HTML = R"MGHTML(<!DOCTYPE html>
<!-- index.html - the structure of the minigit page (what is on the screen).
     Looks are in style.css, behaviour is in app.js. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>minigit</title>
<link rel="stylesheet" href="style.css">
</head>
<body>
<!-- Red warning shown when the minigit program stops answering -->
<div id="conn">Cannot reach the minigit program. Is its window still open?</div>
<!-- Top bar: name, folder, current branch, Undo / Redo / Verify / Stats -->
<header>
  <h1>minigit</h1>
  <span class="dir" id="dir"></span>
  <span id="repoTools" style="display:none"><select id="repoSelectMain"></select><button id="bSwitchRepo">Switch</button><button id="bManageRepos">Repositories</button></span>
  <span id="branchpill"></span>
  <button id="bUndo" title="Undo the last commit, branch, checkout or merge">&#8630; Undo</button>
  <button id="bRedo" title="Redo what was undone">Redo &#8631;</button>
  <button id="bVerify" title="Check every stored object for corruption">Verify</button>
  <button id="bStats" title="Commit and file statistics">Stats</button>
</header>

<!-- Repository manager: each repository is stored in Repositories/<name>. -->
<div id="initview" class="center" style="display:none">
  <div class="card">
    <h2>MiniGitX Repository Manager</h2>
    <p class="hint">Create a named repository or open an existing one. Every repository is stored inside the Repositories folder.</p>
    <div class="empty" id="initdir" style="margin-bottom:10px"></div>
    <div class="field"><label>New repository name</label><input type="text" id="iRepo" placeholder="e.g. CollegeProject"></div>
    <div class="field"><label>Your name</label><input type="text" id="iName" placeholder="e.g. Ayush"></div>
    <div class="field"><label>Your email</label><input type="text" id="iMail" placeholder="e.g. you@example.com"></div>
    <button class="primary" id="bInit">Create repository</button>
    <div class="sep"></div>
    <h3>Existing repositories</h3>
    <div class="row">
      <select id="repoSelect"><option value="">Select a repository</option></select>
      <button id="bOpenRepo">Open repository</button>
    </div>
    <div class="hint">Repository data and files will remain inside each repository's own folder.</div>
  </div>
</div>

<!-- Main screen: left column = work, right column = history -->
<main id="mainview" style="display:none">
  <div class="col">
    <!-- Step 1: write your data on the editor page (opens in a new tab), then stage it here -->
    <div class="card">
      <h2>1 &middot; Write your data, then stage it</h2>
      <p class="hint">Write or change files on the editor page, then come back here and stage the changes.</p>
      <div class="row">
        <a class="btn primary" href="editor.html" target="_blank" rel="noopener">Open file editor &#8599;</a>
      </div>
      <div class="changeinfo" id="changeinfo"></div>
      <div class="row">
        <button id="bStageAll">Stage all changes</button>
        <button id="bChanges">Show changes</button>
      </div>
    </div>

    <div class="card">
      <h2>2 &middot; Commit staged files</h2>
      <div class="row">
        <input type="text" id="cMsg" placeholder="Commit message">
        <button class="primary" id="bCommit">Commit</button>
      </div>
      <div class="empty" id="stagedinfo"></div>
    </div>

    <div class="card">
      <h2>Branches</h2>
      <div class="branches" id="branches"></div>
      <div class="row"><input type="text" id="nbName" placeholder="new branch name"><button id="bNewBranch">Create &amp; switch</button></div>
      <div class="sep"></div>
      <div class="row"><select id="mergeSel"></select><button id="bMerge">Merge into current</button></div>
    </div>
  </div>

  <div class="col">
    <div id="mergebanner"></div>
    <div class="card">
      <h2>3 &middot; History</h2>
      <div class="row" style="margin-bottom:12px">
        <input type="text" id="sQ" placeholder="Search commits by word or prefix (uses the trie)">
        <button id="bSearch">Search</button>
      </div>
      <div class="results" id="results"></div>
      <div class="hist" id="hist"></div>
      <div class="detail" id="detail" style="display:none"></div>
    </div>
    <div class="card" id="diffcard" style="display:none">
      <h2 id="difftitle">Changes</h2>
      <pre class="diff" id="diffbox"></pre>
    </div>
  </div>
</main>

<!-- Bottom panel: shows the real minigit command behind every click -->
<div id="consolewrap">
  <div class="bar"><span>Command output</span><button id="bClear">Clear</button></div>
  <div id="console"></div>
</div>


<script src="app.js"></script>
</body>
</html>
)MGHTML";

const char* const UI_CSS = R"MGCSS(/* style.css - all colours, spacing and layout of the minigit page.
   Change a value here, save, and press F5 in the browser to see it.
   (:root holds the colour palette used everywhere below.) */

:root{
  color-scheme:dark;          /* makes scrollbars and form controls dark too */
  --bg:#000000;               /* page background */
  --card:#111111;             /* boxes */
  --ink:#e8eaf0;              /* main text */
  --muted:#9aa3b8;            /* secondary text */
  --line:#2a2f3a;             /* borders */
  --field:#0a0a0a;            /* input boxes */
  --btn:#1c1f29;              /* buttons */
  --hover:#1a1d26;            /* row hover */
  --sel:#172554;              /* selected row */
  --accent:#60a5fa;           /* links, highlights (text) */
  --accent-bg:#2563eb;        /* filled blue buttons */
  --ok:#4ade80;--warn:#fbbf24;--bad:#f87171
}
*{box-sizing:border-box}
body{margin:0;font:14px/1.45 "Segoe UI",system-ui,Arial,sans-serif;background:var(--bg);color:var(--ink);padding-bottom:230px}
/* ---- top bar ---- */
header{background:#0a0a0a;border-bottom:1px solid var(--line);color:#fff;padding:10px 20px;display:flex;align-items:center;gap:14px;flex-wrap:wrap;position:sticky;top:0;z-index:5}
header h1{font-size:18px;margin:0;letter-spacing:.3px}
header .dir{color:#9ca3af;font-size:12px;flex:1;min-width:120px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.pill{display:inline-block;padding:2px 10px;border-radius:99px;font-size:12px;font-weight:600;background:#1f2937;color:#e5e7eb}
.pill.branch{background:#1d4ed8;color:#fff}
/* ---- buttons and inputs ---- */
button{font:inherit;cursor:pointer;border:1px solid var(--line);background:var(--btn);color:var(--ink);padding:6px 12px;border-radius:7px}
button:hover:not(:disabled){border-color:var(--accent);color:var(--accent)}
button:disabled{opacity:.45;cursor:default}
button.primary{background:var(--accent-bg);border-color:var(--accent-bg);color:#fff}
button.primary:hover:not(:disabled){background:#1d4ed8;border-color:#1d4ed8;color:#fff}
button.danger:hover:not(:disabled){border-color:var(--bad);color:var(--bad)}
button.small{padding:2px 9px;font-size:12px}
header button{background:#1f2937;border-color:#374151;color:#e5e7eb}
header button:hover:not(:disabled){background:#374151;color:#fff;border-color:#4b5563}
input[type=text],select,textarea{font:inherit;padding:7px 9px;border:1px solid var(--line);border-radius:7px;width:100%;background:var(--field);color:var(--ink)}
input:focus,select:focus,textarea:focus{outline:2px solid #1d4ed8;border-color:var(--accent)}
textarea{font-family:Consolas,"Courier New",monospace;font-size:13px;min-height:120px;resize:vertical}
/* ---- page layout: two columns ---- */
main{display:grid;grid-template-columns:minmax(330px,430px) 1fr;gap:16px;padding:16px 20px;align-items:start}
@media(max-width:900px){main{grid-template-columns:1fr}}
.col{display:flex;flex-direction:column;gap:16px;min-width:0}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:14px 16px}
.card h2{font-size:12px;margin:0 0 10px;color:var(--muted);text-transform:uppercase;letter-spacing:.8px}
.row{display:flex;gap:8px;align-items:center}
.row>input,.row>select{flex:1}
/* ---- file list, badges, branches ---- */
.files{list-style:none;margin:0 0 10px;padding:0;max-height:230px;overflow:auto}
.files li{display:flex;align-items:center;gap:8px;padding:5px 4px;border-bottom:1px solid var(--line)}
.files li:last-child{border:0}
.files .name{flex:1;cursor:pointer;word-break:break-all;font-family:Consolas,monospace;font-size:13px}
.files .name:hover{color:var(--accent);text-decoration:underline}
.badge{font-size:11px;font-weight:600;padding:1px 8px;border-radius:99px;white-space:nowrap}
.badge.ok{background:#14532d;color:#86efac}.badge.warn{background:#451a03;color:#fcd34d}
.badge.muted{background:#262b36;color:#aeb6c8}.badge.clean{background:#181b23;color:#8a93a8;font-weight:400}
.empty{color:var(--muted);padding:6px 0}
.branches{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:12px}
.bpill{display:flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:99px;padding:3px 4px 3px 12px;font-weight:600}
.bpill.cur{background:#172554;border-color:#1d4ed8;color:#93c5fd}
.bpill .tip{font:11px Consolas,monospace;color:var(--muted);font-weight:400}
.sep{height:1px;background:var(--line);margin:12px 0}
.banner{border-radius:10px;padding:10px 14px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.banner.warn{background:#2a1c05;border:1px solid #92400e;color:#fcd34d}
.banner.bad{background:#2d0a0a;border:1px solid #991b1b;color:#fca5a5}
.banner span{flex:1}
/* ---- commit history (the graph itself is drawn in app.js) ---- */
.hist{position:relative;overflow-x:auto}
.hist svg{position:absolute;left:0;top:0;pointer-events:none}
.crow{display:flex;align-items:center;gap:10px;cursor:pointer;border-radius:8px;white-space:nowrap}
.crow:hover{background:var(--hover)}.crow.sel{background:var(--sel)}
.crow .hash{font:12px Consolas,monospace;color:var(--accent)}
.crow .msg{font-weight:600;overflow:hidden;text-overflow:ellipsis;max-width:340px}
.crow .meta{margin-left:auto;color:var(--muted);font-size:12px;padding-right:8px}
.tag{font-size:11px;font-weight:700;padding:1px 8px;border-radius:5px}
.tag.head{background:#1d4ed8;color:#fff}.tag.br{background:#14532d;color:#86efac}
.detail{margin-top:12px;border-top:1px solid var(--line);padding-top:12px}
.detail .kv{color:var(--muted);font-size:13px}.detail code{font-family:Consolas,monospace;font-size:12px;color:var(--ink)}
.detail .msgfull{font-size:15px;font-weight:600;margin:4px 0 8px;white-space:pre-wrap}
pre.diff{margin:10px 0 0;background:#0a0f1c;border:1px solid var(--line);color:#e2e8f0;border-radius:9px;padding:10px 12px;max-height:300px;overflow:auto;font:12px/1.5 Consolas,"Courier New",monospace}
pre.diff .a{color:#4ade80}pre.diff .d{color:#f87171}pre.diff .h{color:#60a5fa}pre.diff .f{color:#fff;font-weight:700}pre.diff .t{color:#fbbf24;font-weight:700}
.results{margin-top:8px}.results div{padding:4px 6px;border-radius:6px;cursor:pointer}.results div:hover{background:var(--sel)}
.results code{color:var(--accent);margin-right:8px}
/* ---- command output panel at the bottom ---- */
#consolewrap{position:fixed;left:0;right:0;bottom:0;background:#050505;color:#d1d5db;border-top:3px solid #1f2937;z-index:6}
#consolewrap .bar{display:flex;justify-content:space-between;align-items:center;padding:5px 16px;color:#9ca3af;font-size:12px;text-transform:uppercase;letter-spacing:.8px}
#consolewrap button{background:transparent;color:#9ca3af;border-color:#374151;padding:1px 9px;font-size:12px}
#console{height:170px;overflow:auto;padding:4px 16px 10px;font:13px/1.5 Consolas,"Courier New",monospace}
#console .cmd{color:#67e8f9;margin-top:6px}#console .out{white-space:pre-wrap}
#console .err{color:#fca5a5;white-space:pre-wrap}#console .note{color:#86efac}
.center{max-width:520px;margin:60px auto;text-align:center}
.center .card{text-align:left}.center h2{font-size:20px;color:var(--ink);text-transform:none;letter-spacing:0}
.field{margin:10px 0}.field label{display:block;font-size:12px;color:var(--muted);margin-bottom:3px}
#conn{display:none;background:#b91c1c;color:#fff;text-align:center;padding:6px;font-weight:600}

/* ---- link that looks like a button, hints, change summary ---- */
a.btn{display:inline-block;text-decoration:none;font:inherit;padding:6px 12px;border-radius:7px;border:1px solid var(--line);background:var(--btn);color:var(--ink)}
a.btn:hover{border-color:var(--accent);color:var(--accent)}
a.btn.primary{background:var(--accent-bg);border-color:var(--accent-bg);color:#fff}
a.btn.primary:hover{background:#1d4ed8;border-color:#1d4ed8;color:#fff}
.hint{margin:0 0 10px;color:var(--muted)}
.changeinfo{margin:12px 0;padding:8px 10px;background:#181b23;border-radius:8px;color:var(--ink)}

/* ---- editor page (editor.html) ---- */
.editor-layout{display:grid;grid-template-columns:minmax(240px,320px) 1fr;gap:16px;padding:16px 20px;align-items:start}
@media(max-width:800px){.editor-layout{grid-template-columns:1fr}}
.editor-layout textarea{min-height:380px}
.savemsg{margin-top:10px;min-height:20px;color:var(--ok)}
.savemsg.bad{color:var(--bad)}
header a{color:#93c5fd;text-decoration:none}
header a:hover{text-decoration:underline}
body.editor{padding-bottom:0}
)MGCSS";

const char* const UI_JS = R"MGJS(/* app.js - the behaviour of the minigit page.
   It talks to minigit.exe over three simple web addresses:
     GET  /api/state  -> everything the page needs to draw itself (JSON)
     POST /api/run    -> runs one minigit command, e.g. "commit" "-m" "message"
   (Writing data into files is done by the separate page editor.html / editor.js.)
   Sections: talking to the program / drawing the page / commit graph / buttons. */

(function(){
'use strict';
var $ = function(id){ return document.getElementById(id); };
var esc = function(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); };
var COLORS = ['#2563eb','#db2777','#059669','#d97706','#7c3aed','#0891b2'];
var S = null, lastJson = '', selected = null;

/* ---------- talking to the program ---------- */
function call(url, opts){
  opts = opts || {};
  opts.headers = Object.assign({'X-Minigit':'1'}, opts.headers || {});
  return fetch(url, opts);
}
async function exec(args){
  var r = await call('/api/run', {method:'POST', body: args.join('\n')});
  var j = await r.json();
  if (j.error && !('ok' in j)) return {ok:false, output:'', error:'fatal: ' + j.error + '\n'};
  return j;
}
function quote(a){ return /[\s"]/.test(a) ? '"' + a.replace(/"/g,'\\"') + '"' : a; }
function addLog(cmd, out, err, ok){
  var box = $('console');
  var d = document.createElement('div'); d.className = 'cmd'; d.textContent = '> ' + cmd; box.appendChild(d);
  if (out){ var o = document.createElement('div'); o.className = 'out'; o.textContent = out.replace(/\s+$/,''); box.appendChild(o); }
  if (err){ var e = document.createElement('div'); e.className = 'err'; e.textContent = err.replace(/\s+$/,''); box.appendChild(e); }
  if (!out && !err && ok){ var n = document.createElement('div'); n.className = 'note'; n.textContent = 'done'; box.appendChild(n); }
  while (box.children.length > 300) box.removeChild(box.firstChild);
  box.scrollTop = box.scrollHeight;
}
function note(text, bad){
  var box = $('console'), d = document.createElement('div');
  d.className = bad ? 'err' : 'note'; d.textContent = text; box.appendChild(d); box.scrollTop = box.scrollHeight;
}
async function run(args){
  var j = await exec(args);
  addLog('minigit ' + args.map(quote).join(' '), j.output, j.error, j.ok);
  await refresh(true);
  return j;
}
async function refresh(force){
  try{
    var r = await call('/api/state'); var t = await r.text();
    $('conn').style.display = 'none';
    if (!force && t === lastJson) return;
    lastJson = t; S = JSON.parse(t); render();
  }catch(e){ $('conn').style.display = 'block'; }
}

/* ---------- rendering ---------- */
function firstLine(s){ return String(s).split('\n')[0]; }
function fmtDate(ts){ return new Date(ts * 1000).toLocaleString([], {dateStyle:'medium', timeStyle:'short'}); }

function fillRepositorySelect(id, selected){
  var el = $(id); if (!el) return;
  var html = '<option value="">Select a repository</option>';
  (S.repositories || []).forEach(function(name){
    html += '<option value="' + esc(name) + '"' + (name === selected ? ' selected' : '') + '>' + esc(name) + '</option>';
  });
  el.innerHTML = html;
}
function render(){
  $('dir').textContent = S.cwd;
  fillRepositorySelect('repoSelect', '');
  fillRepositorySelect('repoSelectMain', S.selectedRepo || '');
  if (!S.selectedRepo || !S.initialized){
    $('initview').style.display = ''; $('mainview').style.display = 'none';
    $('repoTools').style.display = 'none';
    $('initdir').textContent = S.cwd + '/Repositories'; $('branchpill').innerHTML = '';
    $('bUndo').disabled = $('bRedo').disabled = $('bVerify').disabled = $('bStats').disabled = true;
    return;
  }
  $('initview').style.display = 'none'; $('mainview').style.display = '';
  $('repoTools').style.display = '';
  $('bUndo').disabled = !S.canUndo; $('bRedo').disabled = !S.canRedo;
  $('bVerify').disabled = $('bStats').disabled = false;
  $('branchpill').innerHTML = S.branch ? '<span class="pill branch">on ' + esc(S.branch) + '</span>'
                                       : '<span class="pill">detached HEAD</span>';
  renderChanges(); renderCommit(); renderBranches(); renderBanner(); renderHistory();
}

/* A short summary instead of a file list: how much is waiting to be staged. */
function renderChanges(){
  var untracked = S.untracked.length, modified = S.unstaged.length, staged = S.staged.length;
  var waiting = untracked + modified, parts = [];
  if (untracked) parts.push(untracked + ' new');
  if (modified) parts.push(modified + ' changed');
  var text = waiting ? 'Waiting to be staged: ' + parts.join(', ') + '.' : 'Nothing waiting to be staged.';
  if (staged) text += ' Staged and ready to commit: ' + staged + '.';
  $('changeinfo').textContent = text;
  $('bStageAll').disabled = !waiting;
}

function renderCommit(){
  var n = S.staged.length;
  $('bCommit').disabled = !(n > 0 || S.merging);
  $('stagedinfo').textContent = n ? n + ' file(s) staged and ready to commit.' : 'Nothing staged yet. Use "Stage all changes" in step 1.';
}

function renderBranches(){
  $('branches').innerHTML = S.branches.length ? S.branches.map(function(b){
    var cur = b.name === S.branch;
    return '<div class="bpill' + (cur ? ' cur' : '') + '">' + (cur ? '&#10003; ' : '') + esc(b.name) +
      ' <span class="tip">' + esc(b.tip.slice(0,7)) + '</span>' +
      (cur ? '' : '<button class="small" data-switch="' + esc(b.name) + '">Switch</button>') + '</div>';
  }).join('') : '<span class="empty">No branch yet. It appears after your first commit.</span>';
  var others = S.branches.filter(function(b){ return b.name !== S.branch; });
  $('mergeSel').innerHTML = others.length ? others.map(function(b){ return '<option>' + esc(b.name) + '</option>'; }).join('')
                                          : '<option value="">(no other branch)</option>';
  $('bMerge').disabled = !others.length || S.merging;
}

function renderBanner(){
  $('mergebanner').innerHTML = S.merging
    ? '<div class="banner warn"><span><b>Merge in progress.</b> Open the conflicted files in the file editor (look for &lt;&lt;&lt;&lt;&lt;&lt;&lt;), fix them, Stage all changes, then Commit.</span><button id="bAbort" class="danger">Abort merge</button></div>' : '';
}

/* ---------- commit graph ---------- */
function layout(commits){
  var lanes = [], pos = {};
  commits.forEach(function(c, row){
    var lane = lanes.indexOf(c.hash);
    if (lane < 0){ lane = lanes.indexOf(null); if (lane < 0){ lane = lanes.length; lanes.push(null); } }
    for (var i = 0; i < lanes.length; i++) if (i !== lane && lanes[i] === c.hash) lanes[i] = null;
    pos[c.hash] = {row: row, lane: lane};
    lanes[lane] = c.parents.length ? c.parents[0] : null;
    for (var k = 1; k < c.parents.length; k++){
      var p = c.parents[k];
      if (lanes.indexOf(p) < 0){ var e = lanes.indexOf(null); if (e < 0){ e = lanes.length; lanes.push(null); } lanes[e] = p; }
    }
  });
  return pos;
}

function renderHistory(){
  var C = S.commits, box = $('hist');
  if (!C.length){ box.innerHTML = '<div class="empty">No commits yet. Stage a file, then press Commit.</div>'; $('detail').style.display = 'none'; return; }
  var pos = layout(C), maxLane = 0;
  Object.keys(pos).forEach(function(h){ if (pos[h].lane > maxLane) maxLane = pos[h].lane; });
  var LW = 20, RH = 46, GW = (maxLane + 1) * LW + 20;
  function X(l){ return 14 + l * LW; }
  function Y(r){ return r * RH + RH / 2; }
  var tips = {}; S.branches.forEach(function(b){ (tips[b.tip] = tips[b.tip] || []).push(b.name); });

  var svg = '<svg width="' + GW + '" height="' + (C.length * RH) + '">', dots = '';
  C.forEach(function(c){
    var a = pos[c.hash];
    c.parents.forEach(function(p, i){
      var b = pos[p]; if (!b) return;
      var col = COLORS[(i ? b.lane : a.lane) % COLORS.length];
      var x1 = X(a.lane), y1 = Y(a.row), x2 = X(b.lane), y2 = Y(b.row);
      svg += x1 === x2 ? '<line x1="' + x1 + '" y1="' + y1 + '" x2="' + x2 + '" y2="' + y2 + '" stroke="' + col + '" stroke-width="2.5"/>'
        : '<path d="M' + x1 + ' ' + y1 + ' C ' + x1 + ' ' + (y1 + RH * .8) + ', ' + x2 + ' ' + (y2 - RH * .8) + ', ' + x2 + ' ' + y2 +
          '" fill="none" stroke="' + col + '" stroke-width="2.5"/>';
    });
    var col2 = COLORS[a.lane % COLORS.length], isHead = c.hash === S.head, isSel = c.hash === selected;
    dots += '<circle cx="' + X(a.lane) + '" cy="' + Y(a.row) + '" r="' + (isSel ? 8 : 6.5) + '" fill="' + col2 + '" stroke="' +
            (isHead ? '#ffffff' : '#111111') + '" stroke-width="' + (isHead ? 3 : 2) + '"/>';
  });
  svg += dots + '</svg>';

  box.innerHTML = svg + C.map(function(c){
    var tags = '';
    if (c.hash === S.head) tags += '<span class="tag head">HEAD' + (S.branch ? ' &rarr; ' + esc(S.branch) : '') + '</span> ';
    (tips[c.hash] || []).forEach(function(n){ if (n !== S.branch || c.hash !== S.head) tags += '<span class="tag br">' + esc(n) + '</span> '; });
    return '<div class="crow' + (c.hash === selected ? ' sel' : '') + '" data-commit="' + c.hash + '" style="height:' + RH + 'px;padding-left:' + GW + 'px">' +
      '<span class="hash">' + c.hash.slice(0, 7) + '</span><span class="msg">' + esc(firstLine(c.message)) + '</span>' + tags +
      '<span class="meta">' + esc(c.author) + ' &middot; ' + esc(fmtDate(c.timestamp)) + '</span></div>';
  }).join('');
  renderDetail();
}

function renderDetail(){
  var d = $('detail'), c = null;
  S.commits.forEach(function(x){ if (x.hash === selected) c = x; });
  if (!c){ d.style.display = 'none'; return; }
  d.style.display = '';
  d.innerHTML = '<div class="kv">commit <code>' + c.hash + '</code></div>' +
    '<div class="msgfull">' + esc(c.message) + '</div>' +
    '<div class="kv">' + esc(c.author) + ' &lt;' + esc(c.email) + '&gt; &middot; ' + esc(fmtDate(c.timestamp)) + '</div>' +
    '<div class="kv">parents: ' + (c.parents.length ? c.parents.map(function(p){ return '<code>' + p.slice(0,7) + '</code>'; }).join(' ') : 'none (first commit)') +
    (c.parents.length > 1 ? ' &mdash; this is a merge commit' : '') + '</div>' +
    '<div class="row" style="margin-top:10px"><button id="bShowCommit">Show what changed</button>' +
    '<button id="bCheckoutCommit">Checkout this commit</button></div>';
}

/* ---------- diff pane ---------- */
function showDiff(title, text){
  $('diffcard').style.display = ''; $('difftitle').textContent = title;
  $('diffbox').innerHTML = esc(text).split('\n').map(function(l){
    var c = l.indexOf('###') === 0 ? 't' : l.indexOf('+++') === 0 || l.indexOf('---') === 0 ? 'f'
          : l.charAt(0) === '+' ? 'a' : l.charAt(0) === '-' ? 'd' : l.indexOf('@@') === 0 ? 'h'
          : l.indexOf('diff ') === 0 || l.indexOf('index ') === 0 || l.indexOf('new file') === 0 || l.indexOf('deleted file') === 0 ? 'f' : '';
    return c ? '<span class="' + c + '">' + l + '</span>' : l;
  }).join('\n');
}

/* ---------- actions ---------- */
async function showChanges(){
  var un = await exec(['diff']), stg = await exec(['diff','--staged']), t = '';
  if (un.output) t += '### Not staged yet\n' + un.output;
  if (stg.output) t += (t ? '\n' : '') + '### Staged (will go into the next commit)\n' + stg.output;
  showDiff('Working changes', t || 'No changes. Edit a file and save it.');
}
async function doSearch(){
  var q = $('sQ').value.trim();
  if (!q){ $('results').innerHTML = ''; return; }
  var j = await exec(['search'].concat(q.split(/\s+/)));
  var lines = (j.output || '').split('\n').filter(Boolean);
  $('results').innerHTML = j.ok && lines.length && lines[0] !== 'no commits match'
    ? lines.map(function(l){ var i = l.indexOf(' '); return '<div data-hash="' + esc(l.slice(0, i)) + '"><code>' + esc(l.slice(0, i)) + '</code>' + esc(l.slice(i + 1)) + '</div>'; }).join('')
    : '<div class="empty">No commits match.</div>';
}
function selectCommit(h){ selected = h; renderHistory(); }

document.addEventListener('click', async function(ev){
  var t = ev.target, id = t.id;
  if (t.dataset.switch) return run(['checkout', t.dataset.switch]);
  var row = t.closest ? t.closest('[data-commit]') : null;
  if (row) return selectCommit(row.dataset.commit);
  var hit = t.closest ? t.closest('[data-hash]') : null;
  if (hit){ var h = hit.dataset.hash; S.commits.forEach(function(c){ if (c.hash.indexOf(h) === 0) selectCommit(c.hash); }); return; }
  if (id === 'bInit'){
    var repoName = $('iRepo').value.trim();
    if (!repoName){ note('Enter a repository name first.', true); return; }
    var response = await call('/api/repos', {method:'POST', body: repoName + '\n' + $('iName').value.trim() + '\n' + $('iMail').value.trim()});
    var created = await response.json();
    if (created.error){ note(created.error, true); return; }
    note('Created repository: ' + created.name, false);
    await refresh(true);
  }
  else if (id === 'bOpenRepo'){
    var openName = $('repoSelect').value;
    if (!openName){ note('Select a repository first.', true); return; }
    var opened = await call('/api/select', {method:'POST', body:openName});
    var openedJson = await opened.json();
    if (openedJson.error){ note(openedJson.error, true); return; }
    await refresh(true);
  }
  else if (id === 'bSwitchRepo'){
    var switchName = $('repoSelectMain').value;
    if (!switchName){ note('Select a repository first.', true); return; }
    var switched = await call('/api/select', {method:'POST', body:switchName});
    var switchedJson = await switched.json();
    if (switchedJson.error){ note(switchedJson.error, true); return; }
    selected = null; await refresh(true);
  }
  else if (id === 'bManageRepos'){
    await call('/api/select', {method:'POST', body:''}); selected = null; await refresh(true);
  }
  else if (id === 'bStageAll') await run(['add','.']);
  else if (id === 'bChanges') await showChanges();
  else if (id === 'bCommit'){
    var msg = $('cMsg').value.replace(/\s+/g,' ').trim();
    var j = await run(msg ? ['commit','-m', msg] : ['commit']);
    if (j.ok) $('cMsg').value = '';
  }
  else if (id === 'bNewBranch'){
    var nb = $('nbName').value.trim(); if (!nb){ note('Type a branch name first.', true); return; }
    var j2 = await run(['checkout','-b', nb]); if (j2.ok) $('nbName').value = '';
  }
  else if (id === 'bMerge'){ var b = $('mergeSel').value; if (b) await run(['merge', b]); }
  else if (id === 'bAbort') await run(['merge','--abort']);
  else if (id === 'bUndo') await run(['undo']);
  else if (id === 'bRedo') await run(['redo']);
  else if (id === 'bVerify') await run(['verify']);
  else if (id === 'bStats') await run(['stats']);
  else if (id === 'bSearch') await doSearch();
  else if (id === 'bClear') $('console').innerHTML = '';
  else if (id === 'bShowCommit'){
    var j3 = await exec(['diff', selected]);
    showDiff('Commit ' + selected.slice(0, 7), j3.output || j3.error || 'No file changes in this commit.');
  }
  else if (id === 'bCheckoutCommit') await run(['checkout', selected]);
});
$('cMsg').addEventListener('keydown', function(e){ if (e.key === 'Enter' && !$('bCommit').disabled) $('bCommit').click(); });
$('sQ').addEventListener('keydown', function(e){ if (e.key === 'Enter') doSearch(); });
$('nbName').addEventListener('keydown', function(e){ if (e.key === 'Enter') $('bNewBranch').click(); });

refresh(true);
setInterval(function(){ if (!document.hidden) refresh(false); }, 2500);
})();
)MGJS";

const char* const UI_EDITOR_HTML = R"MGEHTML(<!DOCTYPE html>
<!-- editor.html - a separate page for writing data into files.
     Looks come from style.css, behaviour from editor.js. -->
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>minigit - file editor</title>
<link rel="stylesheet" href="style.css">
</head>
<body class="editor">
<!-- Top bar: title, the project folder, and a link back to the main page -->
<header>
  <h1>File editor</h1>
  <span class="dir" id="dir"></span>
  <a href="/" id="back">&larr; Back to minigit</a>
</header>

<div class="editor-layout">
  <!-- Left: the files in the project folder. Click one to open it. -->
  <div class="card">
    <h2>Files in the project folder</h2>
    <ul class="files" id="files"></ul>
    <button id="bNew">+ New file</button>
  </div>

  <!-- Right: write the data here and press Save -->
  <div class="card">
    <h2>Write data into a file</h2>
    <div class="field" style="margin-top:0">
      <label for="fName">File name</label>
      <input type="text" id="fName" placeholder="for example notes.txt or src/main.cpp">
    </div>
    <div class="field">
      <label for="fText">Content</label>
      <textarea id="fText" placeholder="Type the data you want to store in this file"></textarea>
    </div>
    <div class="row">
      <button class="primary" id="bSave">Save file (Ctrl+S)</button>
      <button class="danger" id="bDelete">Delete file</button>
    </div>
    <div class="savemsg" id="savemsg"></div>
    <p class="hint">After saving, go back to the minigit page and click <b>Stage all changes</b>, then <b>Commit</b>.</p>
  </div>
</div>

<script src="editor.js"></script>
</body>
</html>
)MGEHTML";

const char* const UI_EDITOR_JS = R"MGEJS(/* editor.js - behaviour of the file editor page (editor.html).
   Uses three web addresses of minigit.exe:
     GET  /api/state            -> list of files (and their status)
     GET  /api/file?name=...    -> read a file
     POST /api/save?name=...    -> write a file   (body = the text)
     POST /api/delete?name=...  -> delete a file */
(function(){
'use strict';
var $ = function(id){ return document.getElementById(id); };
var esc = function(s){ return String(s).replace(/[&<>"]/g, function(c){ return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); };
var lastJson = '';

function call(url, opts){
  opts = opts || {};
  opts.headers = Object.assign({'X-Minigit':'1'}, opts.headers || {});
  return fetch(url, opts);
}

function say(text, bad){
  var box = $('savemsg');
  box.textContent = text;
  box.className = 'savemsg' + (bad ? ' bad' : '');
}

/* ---------- the file list ---------- */
async function loadList(force){
  var s;
  try{
    var r = await call('/api/state'); var t = await r.text();
    if (!force && t === lastJson) return;
    lastJson = t; s = JSON.parse(t);
  }catch(e){ say('Cannot reach the minigit program. Is its window still open?', true); return; }

  $('dir').textContent = s.cwd;
  var status = {};
  function add(p, text, cls){ (status[p] = status[p] || []).push([text, cls]); }
  if (s.initialized){
    s.staged.forEach(function(x){ add(x.p, 'staged', 'ok'); });
    s.unstaged.forEach(function(x){ add(x.p, x.s === 'D' ? 'deleted' : 'modified', 'warn'); });
    s.untracked.forEach(function(p){ add(p, 'new', 'muted'); });
  }
  var names = {};
  (s.files || []).forEach(function(p){ names[p] = 1; });
  if (s.initialized) s.staged.concat(s.unstaged).forEach(function(x){ names[x.p] = 1; });
  var list = Object.keys(names).sort();
  $('files').innerHTML = list.length ? list.map(function(p){
    var b = status[p] || [['saved', 'clean']];
    return '<li><span class="name" data-open="' + esc(p) + '">' + esc(p) + '</span>' +
      b.map(function(x){ return '<span class="badge ' + x[1] + '">' + x[0] + '</span>'; }).join('') + '</li>';
  }).join('') : '<li class="empty">No files yet. Type a name on the right and save.</li>';
}

/* ---------- actions ---------- */
async function openFile(name){
  var r = await call('/api/file?name=' + encodeURIComponent(name));
  if (!r.ok){ say('Could not open ' + name, true); return; }
  $('fName').value = name;
  $('fText').value = await r.text();
  say('Opened ' + name);
}

async function saveFile(){
  var name = $('fName').value.trim();
  if (!name){ say('Type a file name first.', true); return; }
  var r = await call('/api/save?name=' + encodeURIComponent(name), {method:'POST', body: $('fText').value});
  var j = await r.json();
  if (j.error){ say('Save failed: ' + j.error, true); return; }
  $('fName').value = j.name;
  say('Saved ' + j.name + '.');
  await loadList(true);
}

async function deleteFile(){
  var name = $('fName').value.trim();
  if (!name){ say('Open or type the file you want to delete.', true); return; }
  if (!confirm('Delete ' + name + ' from the folder?')) return;
  var r = await call('/api/delete?name=' + encodeURIComponent(name), {method:'POST', body:''});
  var j = await r.json();
  if (j.error){ say('Delete failed: ' + j.error, true); return; }
  $('fName').value = ''; $('fText').value = '';
  say('Deleted ' + name + '.');
  await loadList(true);
}

document.addEventListener('click', function(ev){
  var t = ev.target;
  if (t.dataset && t.dataset.open) return openFile(t.dataset.open);
  if (t.id === 'bSave') return saveFile();
  if (t.id === 'bDelete') return deleteFile();
  if (t.id === 'bNew'){ $('fName').value = ''; $('fText').value = ''; say(''); $('fName').focus(); }
});

/* Ctrl+S saves, like in any editor */
document.addEventListener('keydown', function(e){
  if ((e.ctrlKey || e.metaKey) && (e.key === 's' || e.key === 'S')){ e.preventDefault(); saveFile(); }
});

loadList(true);
setInterval(function(){ if (!document.hidden) loadList(false); }, 3000);
})();
)MGEJS";

